def _normalize_page_size(page_size):
    """SPEC-PAGINATION：page_size 上限 100，下限 1，非法值回落到默认值 20。"""
    try:
        value = int(page_size)
    except (TypeError, ValueError):
        return DEFAULT_PAGE_SIZE
    if value > MAX_PAGE_SIZE:
        return MAX_PAGE_SIZE
    if value < 1:
        return DEFAULT_PAGE_SIZE
    return value
